/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3bg {	public static final class Attr {		public static final String bg = "background";		public static final String color = "background-color";		public static final String image = "background-image";		public static final String repeat = "background-repeat";		public static final String attachment = "background-attachment";		public static final String position = "background-position";		public static final String clip = "background-clip";		public static final String origin = "background-origin";		public static final String size = "background-size";	}	public static final class Repeat {		public static final String repeat = "repeat";		public static final String repeatX = "repeat-x";		public static final String repeatY = "repeat-y";		public static final String noRepeat = "no-repeat";		public static final String space = "space";		public static final String round = "round";	}	public static final class Attach {				public static final String scroll = "scroll";		public static final String fixed = "fixed";		public static final String local = "local";	}	public static final class X {		public static final String left = "left";		public static final String center= "center";		public static final String right = "right";	}	public static final class Y {		public static final String top = "top";		public static final String center= "center";		public static final String bottom = "bottom";	}	public static final class Size {		public static final String auto = "auto";		public static final String cover = "cover";		public static final String contain = "contain";	}	public Value bg(String shorthand) {		return new Value().name(Attr.bg).text(shorthand);	}	public Value color(String color) {		return new Value().name(Attr.color).text(color);	}	public Value image(String url) {		return new Value().name(Attr.image).text(String.format("url('%s')", url));	}	public Value repeat(String repeat) {		return new Value().name(Attr.repeat).text(repeat);	}	public Value attachment(String attachment) {		return new Value().name(Attr.attachment).text(attachment);	}	public Value position(String x, String y) {		return new Value().name(Attr.position).text(x + " " + y);	}	public Value clip(String box) {		return new Value().name(Attr.clip).text(box);	}	public Value origin(String box) {		return new Value().name(Attr.origin).text(box);	}	public Value size(String size) {		return new Value().name(Attr.size).text(size);	}}